import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { FaSignInAlt, FaUser, FaLock, FaSparkles } from 'react-icons/fa';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        const success = await login(username, password);
        setLoading(false);
        if (success) navigate('/dashboard');
    };

    return (
        <div className="min-h-screen d-flex align-items-center justify-content-center bg-gradient-to-br from-indigo-50 via-white to-purple-50 p-4">
            <div className="w-100" style={{ maxWidth: '420px' }}>
                <div className="text-center mb-4">
                    <div className="d-inline-flex align-items-center justify-content-center bg-gradient-to-r from-indigo-500 to-purple-600 shadow-lg shadow-indigo-200 rounded-4 mb-3" style={{ width: '64px', height: '64px' }}>
                        <FaSparkles size={28} className="text-white" />
                    </div>
                    <h1 className="fw-bold text-dark">RoadMap Tracker</h1>
                    <p className="text-muted">Sign in to track your progress</p>
                </div>
                <div className="bg-white rounded-4 shadow-lg p-4 p-md-5 border">
                    <form onSubmit={handleSubmit}>
                        <div className="mb-3">
                            <label className="form-label fw-semibold small">Username</label>
                            <div className="position-relative">
                                <FaUser className="position-absolute top-50 start-0 translate-middle-y ms-3 text-muted" size={16} />
                                <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} className="form-control ps-5 py-3 rounded-3 bg-light border-0" placeholder="Enter your username" required />
                            </div>
                        </div>
                        <div className="mb-4">
                            <label className="form-label fw-semibold small">Password</label>
                            <div className="position-relative">
                                <FaLock className="position-absolute top-50 start-0 translate-middle-y ms-3 text-muted" size={16} />
                                <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="form-control ps-5 py-3 rounded-3 bg-light border-0" placeholder="Enter your password" required />
                            </div>
                        </div>
                        <button type="submit" disabled={loading} className="btn btn-primary w-100 py-3 rounded-3 fw-semibold bg-gradient-to-r from-indigo-500 to-purple-600 border-0">
                            <FaSignInAlt className="me-2" /> {loading ? 'Logging in...' : 'Login'}
                        </button>
                    </form>
                    <div className="mt-4 text-center"><p className="text-muted small">Don't have an account? <Link to="/register" className="text-indigo-600 fw-semibold text-decoration-none">Register</Link></p></div>
                </div>
            </div>
        </div>
    );
};

export default Login;
